def _msk_shape(self, block, region):
    """[R54B SK1] tail-IfRegion shape: this block is the loop-tail rejoin."""
    try:
        lp = self._current_loop
        if lp is None or not isinstance(region, IfRegion) or block is None:
            return False
        h = getattr(lp, 'header_block', None)
        if h is None or region.merge_block is not h:
            return False
        last = block.get_last_instruction()
        if (last is None or last.opname not in ('JUMP_BACKWARD',
                                                'JUMP_BACKWARD_NO_INTERRUPT')
                or last.argval is None
                or self.cfg.get_block_by_offset(last.argval) is not h):
            return False
        preds = [p for p in (block.predecessors or []) if p is not block]
        return len(preds) == 1 and preds[0] in (set(region.blocks or [])
                                                | set(region.then_blocks or []))
    except Exception:
        return False

def _msk_claim(self, region):
    """[R54B SK2] claim the unrecognised else arm from CFG shape only."""
    try:
        lp = self._current_loop
        if lp is None or not isinstance(region, IfRegion):
            return False
        h = getattr(lp, 'header_block', None)
        if h is None or region.merge_block is not h:
            return False
        if getattr(region, 'else_blocks', None):
            return False
        ent = getattr(region, 'entry', None)
        if ent is None:
            return False
        own = set(region.blocks or []) | set(region.then_blocks or [])
        f = None
        for s in (ent.successors or []):
            if s in own:
                continue
            if any(i.opname in ('PUSH_EXC_INFO', 'WITH_EXCEPT_START')
                   for i in (s.instructions or [])):
                continue
            f = s
            break
        if f is None or f is h:
            return False
        if f not in (set(lp.body_blocks or []) | {h}):
            return False
        last = f.get_last_instruction()
        if (last is None or last.opname not in ('JUMP_BACKWARD',
                                                'JUMP_BACKWARD_NO_INTERRUPT')
                or last.argval is None
                or self.cfg.get_block_by_offset(last.argval) is not h):
            return False
        mean = [i for i in (f.instructions or [])
                if i.opname not in ('RESUME', 'NOP', 'CACHE', 'PUSH_NULL', 'POP_TOP',
                                    'PRECALL', 'EXTENDED_ARG', 'COPY_FREE_VARS')
                and not i.opname.startswith('JUMP')]
        if not mean:
            return False
        region.else_blocks = [f]
        print('[MSK] CLAIM if_entry=%s else=%s ok=True'
              % (ent.start_offset, f.start_offset))
        return True
    except Exception as _e:
        print('[MSK] CLAIM error %r' % (_e,))
        return False
def _generate_if(self, region: IfRegion) -> Union[Dict[str, Any], List[Dict[str, Any]]]:
    self._msk_claim(region)
